BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE api_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), key_hash bytea NOT NULL UNIQUE, scopes text[] NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), external_ref text NOT NULL, display_name text NOT NULL, billing_email text, status text NOT NULL CHECK(status IN ('active','suspended','deleted')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,external_ref));
CREATE TABLE metrics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), key text NOT NULL, kind text NOT NULL CHECK(kind IN ('counter','gauge')), unit text NOT NULL, display_name text NOT NULL, UNIQUE(organization_id,id), UNIQUE(organization_id,key));
CREATE TABLE plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), plan_key text NOT NULL, current_version integer NOT NULL DEFAULT 1, active boolean NOT NULL DEFAULT true, UNIQUE(organization_id,id), UNIQUE(organization_id,plan_key));
CREATE TABLE plan_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, plan_id uuid NOT NULL, version integer NOT NULL CHECK(version>0), display_name text NOT NULL, currency char(3) NOT NULL DEFAULT 'USD', monthly_base numeric NOT NULL CHECK(monthly_base>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(plan_id,version), FOREIGN KEY(organization_id,plan_id) REFERENCES plans(organization_id,id));
CREATE TABLE plan_metric_prices(organization_id uuid NOT NULL, plan_version_id uuid NOT NULL, metric_id uuid NOT NULL, included numeric NOT NULL CHECK(included>=0), unit text NOT NULL, pricing_tiers jsonb NOT NULL, PRIMARY KEY(plan_version_id,metric_id), FOREIGN KEY(organization_id,plan_version_id) REFERENCES plan_versions(organization_id,id), FOREIGN KEY(organization_id,metric_id) REFERENCES metrics(organization_id,id));
CREATE TABLE plan_entitlements(organization_id uuid NOT NULL, plan_version_id uuid NOT NULL, entitlement_key text NOT NULL, value jsonb NOT NULL, PRIMARY KEY(plan_version_id,entitlement_key), FOREIGN KEY(organization_id,plan_version_id) REFERENCES plan_versions(organization_id,id));
CREATE TABLE subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, customer_id uuid NOT NULL, status text NOT NULL CHECK(status IN ('active','canceled','ended')), period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id), CHECK(period_start<period_end));
CREATE TABLE subscription_segments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, subscription_id uuid NOT NULL, plan_version_id uuid NOT NULL, effective_from timestamptz NOT NULL, effective_to timestamptz NOT NULL, FOREIGN KEY(organization_id,subscription_id) REFERENCES subscriptions(organization_id,id), FOREIGN KEY(organization_id,plan_version_id) REFERENCES plan_versions(organization_id,id), CHECK(effective_from<effective_to), EXCLUDE USING gist (organization_id WITH =, subscription_id WITH =, tstzrange(effective_from,effective_to,'[)') WITH &&));
CREATE INDEX subscription_segments_lookup ON subscription_segments(organization_id,subscription_id,effective_from,effective_to);
CREATE TABLE scheduled_subscription_changes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, subscription_id uuid NOT NULL, target_plan_version_id uuid, change_kind text NOT NULL CHECK(change_kind IN ('plan','cancel')), state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','applied','canceled')), effective_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,subscription_id) REFERENCES subscriptions(organization_id,id), FOREIGN KEY(organization_id,target_plan_version_id) REFERENCES plan_versions(organization_id,id));
CREATE UNIQUE INDEX scheduled_changes_one_pending ON scheduled_subscription_changes(organization_id,subscription_id) WHERE state='pending';
CREATE TABLE usage_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, customer_id uuid NOT NULL, metric_id uuid NOT NULL, source text NOT NULL, idempotency_key text NOT NULL, quantity bigint NOT NULL CHECK(quantity>=0), occurred_at timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), metadata jsonb NOT NULL DEFAULT '{}', UNIQUE(organization_id,source,idempotency_key), FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id), FOREIGN KEY(organization_id,metric_id) REFERENCES metrics(organization_id,id));
CREATE INDEX usage_events_customer_time ON usage_events(organization_id,customer_id,occurred_at,metric_id);
CREATE TABLE storage_balances(organization_id uuid NOT NULL, customer_id uuid NOT NULL, metric_id uuid NOT NULL, bytes bigint NOT NULL CHECK(bytes>=0), changed_at timestamptz NOT NULL, PRIMARY KEY(organization_id,customer_id,metric_id), FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id), FOREIGN KEY(organization_id,metric_id) REFERENCES metrics(organization_id,id));
CREATE TABLE storage_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, customer_id uuid NOT NULL, metric_id uuid NOT NULL, source text NOT NULL, idempotency_key text NOT NULL, bytes_after bigint NOT NULL CHECK(bytes_after>=0), occurred_at timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,source,idempotency_key), FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id), FOREIGN KEY(organization_id,metric_id) REFERENCES metrics(organization_id,id));
CREATE INDEX storage_events_customer_time ON storage_events(organization_id,customer_id,occurred_at);
CREATE TABLE quota_counters(organization_id uuid NOT NULL, customer_id uuid NOT NULL, metric_id uuid NOT NULL, period_start timestamptz NOT NULL, consumed bigint NOT NULL CHECK(consumed>=0), reserved bigint NOT NULL CHECK(reserved>=0), PRIMARY KEY(organization_id,customer_id,metric_id,period_start), FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id), FOREIGN KEY(organization_id,metric_id) REFERENCES metrics(organization_id,id));
CREATE TABLE usage_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, customer_id uuid NOT NULL, metric_id uuid NOT NULL, quantity bigint NOT NULL CHECK(quantity>0), state text NOT NULL CHECK(state IN ('reserved','committed','canceled','expired')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id), FOREIGN KEY(organization_id,metric_id) REFERENCES metrics(organization_id,id));
CREATE TABLE invoice_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, customer_id uuid NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, grace_hours integer NOT NULL DEFAULT 48 CHECK(grace_hours>=0), UNIQUE(organization_id,customer_id,starts_at), FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id), CHECK(starts_at<ends_at));
CREATE TABLE invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, customer_id uuid NOT NULL, period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, currency char(3) NOT NULL, status text NOT NULL CHECK(status IN ('finalized')), subtotal numeric(20,6) NOT NULL, total numeric(20,6) NOT NULL, finalized_at timestamptz NOT NULL, UNIQUE(organization_id,customer_id,period_start), FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id));
ALTER TABLE invoices ADD CONSTRAINT invoices_org_id_unique UNIQUE(organization_id,id);
CREATE TABLE invoice_line_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, invoice_id uuid NOT NULL, description text NOT NULL, quantity numeric NOT NULL, unit text NOT NULL, rate numeric NOT NULL, amount numeric(20,6) NOT NULL, pricing_reference jsonb NOT NULL, FOREIGN KEY(organization_id,invoice_id) REFERENCES invoices(organization_id,id));
CREATE TABLE billing_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, customer_id uuid NOT NULL, invoice_id uuid, amount numeric(20,2) NOT NULL CHECK(amount<>0), reason text NOT NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,customer_id) REFERENCES customers(organization_id,id), FOREIGN KEY(organization_id,invoice_id) REFERENCES invoices(organization_id,id));
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), actor text NOT NULL, action text NOT NULL, target_type text NOT NULL, target_id text NOT NULL, details jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION reject_immutable_record_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'immutable billing evidence cannot be updated or deleted';
END;
$$;
CREATE TRIGGER plan_versions_immutable BEFORE UPDATE OR DELETE ON plan_versions FOR EACH ROW EXECUTE FUNCTION reject_immutable_record_mutation();
CREATE TRIGGER plan_metric_prices_immutable BEFORE UPDATE OR DELETE ON plan_metric_prices FOR EACH ROW EXECUTE FUNCTION reject_immutable_record_mutation();
CREATE TRIGGER plan_entitlements_immutable BEFORE UPDATE OR DELETE ON plan_entitlements FOR EACH ROW EXECUTE FUNCTION reject_immutable_record_mutation();
CREATE TRIGGER usage_events_immutable BEFORE UPDATE OR DELETE ON usage_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_record_mutation();
CREATE TRIGGER storage_events_immutable BEFORE UPDATE OR DELETE ON storage_events FOR EACH ROW EXECUTE FUNCTION reject_immutable_record_mutation();
CREATE TRIGGER invoices_immutable BEFORE UPDATE OR DELETE ON invoices FOR EACH ROW EXECUTE FUNCTION reject_immutable_record_mutation();
CREATE TRIGGER invoice_line_items_immutable BEFORE UPDATE OR DELETE ON invoice_line_items FOR EACH ROW EXECUTE FUNCTION reject_immutable_record_mutation();
CREATE TRIGGER audit_logs_immutable BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION reject_immutable_record_mutation();
CREATE TRIGGER billing_adjustments_immutable BEFORE UPDATE OR DELETE ON billing_adjustments FOR EACH ROW EXECUTE FUNCTION reject_immutable_record_mutation();
-- RLS fails closed unless each runtime transaction sets its authenticated tenant ID.
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY;
ALTER TABLE organizations FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON organizations USING (id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE api_keys ENABLE ROW LEVEL SECURITY;
ALTER TABLE api_keys FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON api_keys USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE customers ENABLE ROW LEVEL SECURITY;
ALTER TABLE customers FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON customers USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE metrics ENABLE ROW LEVEL SECURITY;
ALTER TABLE metrics FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON metrics USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE plans FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON plans USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE plan_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE plan_versions FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON plan_versions USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE plan_metric_prices ENABLE ROW LEVEL SECURITY;
ALTER TABLE plan_metric_prices FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON plan_metric_prices USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE plan_entitlements ENABLE ROW LEVEL SECURITY;
ALTER TABLE plan_entitlements FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON plan_entitlements USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE subscriptions FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON subscriptions USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE subscription_segments ENABLE ROW LEVEL SECURITY;
ALTER TABLE subscription_segments FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON subscription_segments USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE scheduled_subscription_changes ENABLE ROW LEVEL SECURITY;
ALTER TABLE scheduled_subscription_changes FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON scheduled_subscription_changes USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE usage_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE usage_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON usage_events USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE storage_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE storage_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON storage_events USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE storage_balances ENABLE ROW LEVEL SECURITY;
ALTER TABLE storage_balances FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON storage_balances USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE quota_counters ENABLE ROW LEVEL SECURITY;
ALTER TABLE quota_counters FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON quota_counters USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE usage_reservations ENABLE ROW LEVEL SECURITY;
ALTER TABLE usage_reservations FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON usage_reservations USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE invoice_periods ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoice_periods FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON invoice_periods USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoices FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON invoices USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE invoice_line_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE invoice_line_items FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON invoice_line_items USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE billing_adjustments ENABLE ROW LEVEL SECURITY;
ALTER TABLE billing_adjustments FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON billing_adjustments USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_logs FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON audit_logs USING (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid) WITH CHECK (organization_id = NULLIF(current_setting('app.organization_id', true), '')::uuid);
COMMIT;
